package com.abhishek.ecommerce.notification;import com.abhishek.ecommerce.common.DomainEvent;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;@Component public class NotificationConsumer{@KafkaListener(topics={"order-events","payment-events"},groupId="notification-service")void onEvent(DomainEvent e){System.out.printf("[NOTIFICATION] type=%s aggregate=%s user=%s%n",e.eventType(),e.aggregateId(),e.userId());}}